local UIModule = CS.Engine.UI.UIModule

---@class JapaneseStoryUtils
local JapaneseStoryUtils = Class("JapaneseStoryUtils")
JapaneseStoryUtils.TaskType = {
    Task = 1,
    Achievement = 2,
}


---进入活动
function JapaneseStoryUtils.Entry(excludeIds, parameter, isStack)
    isStack = isStack ~= false
    UIModule.OpenDialog(
            { id = Constants.UITypeIds.JapaneseStoryEntryMain, parameters = parameter },
            excludeIds,
            isStack
    )
end

---获取参数表配置
function JapaneseStoryUtils.GetConfigParamsById(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6491, "JapaneseStoryParamsVo", id)
    if vo == nil then
        printError("和风副本参数表 中未找到 %s", id)
        return 0
    end
    return checkInt(vo.num)
end

return JapaneseStoryUtils